1	package darksafe
2	
3	import (
4		"strings"
5		"testing"
6	)
7	
8	// 损坏文本必须作为整行解析失败：不带 index、不带 conflict，且不与用户显式
9	// 写入的 U+FFFD 序列发生身份合并。写入与查询两条入口行为一致。
10	
11	// assertWholeLineTextError 校验损坏文本产生的整行错误：无 index、无 conflict、
12	// 错误原因包含 want 子串（用于区分 UTF-8 与代理项两类原因）。
13	func assertWholeLineTextError(t *testing.T, lerr *LineError, want string) {
14		t.Helper()
15		if lerr == nil {
16			t.Fatalf("expected whole-line failure, got success")
17		}
18		if lerr.Index != 0 {
19			t.Fatalf("corrupt text must fail the whole line without index, got index=%d", lerr.Index)
20		}
21		if lerr.Conflict != nil {
22			t.Fatalf("corrupt text must not report a conflict, got %+v", lerr.Conflict)
23		}
24		if !strings.Contains(lerr.Error, want) {
25			t.Fatalf("error = %q, want substring %q", lerr.Error, want)
26		}
27	}
28	
29	func TestCorruptSurrogateEscapesRejected(t *testing.T) {
30		bad := []string{
31			`[{"name":"m\uD800","timestamp":1,"value":1}]`,                    // 单独高代理项
32			`[{"name":"m\uDFFF","timestamp":1,"value":1}]`,                    // 高代理项区间末端
33			`[{"name":"m\uDC00","timestamp":1,"value":1}]`,                    // 单独低代理项
34			`[{"name":"m\uDfff","timestamp":1,"value":1}]`,                    // 小写十六进制的低代理项
35			`[{"name":"m\uD800A","timestamp":1,"value":1}]`,                   // 高代理项后不是转义而是普通字符
36			`[{"name":"m\uD800\uD800","timestamp":1,"value":1}]`,              // 高代理项后紧跟另一个高代理项
37			`[{"name":"m\uD800\\uDE00","timestamp":1,"value":1}]`,             // 高代理项后是被转义的反斜杠
38			`[{"name":"m","timestamp":1,"value":1,"labels":{"k":"x\uD800"}}]`, // 标签值
39			`[{"name":"m","timestamp":1,"value":1,"labels":{"k\uD800":"v"}}]`, // 标签键
40		}
41		for _, line := range bad {
42			store := NewMetricStore()
43			_, lerr := store.IngestLine(line)
44			assertWholeLineTextError(t, lerr, "surrogate")
45			if got := len(mustOK(t, store, `[]`).Series); got != 0 {
46				t.Fatalf("line %s: failed line must write no points, series=%d", line, got)
47			}
48		}
49	}
50	
51	func TestCorruptSurrogateInQueryRejected(t *testing.T) {
52		store := NewMetricStore()
53		mustOK(t, store, `[{"name":"m�","timestamp":1,"value":7}]`)
54		badQueries := []string{
55			`{"op":"query","name":"m\uD800","start":0,"end":10}`,
56			`{"op":"query","name":"m","start":0,"end":10,"labels":{"k":"v\uDC00"}}`,
57			`{"op":"query","name":"m","start":0,"end":10,"labels":{"k\uD800":"v"}}`,
58		}
59		for _, q := range badQueries {
60			_, lerr := store.QueryLine(q)
61			assertWholeLineTextError(t, lerr, "surrogate")
62		}
63		// 损坏查询绝不能经替换后命中用户显式写入的 U+FFFD 序列（上面已尝试 m\uD800）。
64		res := mustQuery(t, store, `{"op":"query","name":"m�","start":0,"end":10}`)
65		if len(res.Series) != 1 || res.Series[0].Average != 7 {
66			t.Fatalf("real U+FFFD series still queryable, got %+v", res.Series)
67		}
68	}
69	
70	func TestInvalidUTF8BytesRejected(t *testing.T) {
71		cases := [][]byte{
72			[]byte(`[{"name":"m` + "\xed\xa0\x80" + `","timestamp":1,"value":1}]`),
73			[]byte(`[{"name":"m` + "\xff" + `","timestamp":1,"value":1}]`),
74			[]byte(`[{"name":"m","timestamp":1,"value":1,"labels":{"k":"` + "\xff" + `"}}]`),
75			[]byte(`[{"name":"m","timestamp":1,"value":1,"labels":{"` + "\xfe" + `":"v"}}]`),
76		}
77		for _, raw := range cases {
78			store := NewMetricStore()
79			_, lerr := store.IngestLine(string(raw))
80			assertWholeLineTextError(t, lerr, "UTF-8")
81			if got := len(mustOK(t, store, `[]`).Series); got != 0 {
82				t.Fatalf("raw %v: failed line must write nothing, series=%d", raw, got)
83			}
84		}
85	
86		// 查询同样拒绝非法字节，且不返回替换后的匹配。
87		store := NewMetricStore()
88		mustOK(t, store, `[{"name":"m�","timestamp":1,"value":3}]`)
89		q := []byte(`{"op":"query","name":"m` + "\xff" + `","start":0,"end":10}`)
90		_, lerr := store.QueryLine(string(q))
91		assertWholeLineTextError(t, lerr, "UTF-8")
92	}
93	
94	func TestCorruptLineDoesNotMergeWithReplacementCharSeries(t *testing.T) {
95		// 先写入一个用户显式命名为 “m�” 的序列。
96		store := NewMetricStore()
97		mustOK(t, store, `[{"name":"m�","timestamp":1,"value":7}]`)
98	
99		// 同值：损坏输入若被替换成 U+FFFD 会被误判为重复而成功——现在必须整行失败。
100		_, lerr := store.IngestLine(`[{"name":"m\uD800","timestamp":1,"value":7}]`)
101		assertWholeLineTextError(t, lerr, "surrogate")
102	
103		// 不同值：旧行为会误报与 U+FFFD 序列冲突——现在只是整行文本错误，无 conflict。
104		_, lerr = store.IngestLine(`[{"name":"m\uD800","timestamp":1,"value":9}]`)
105		assertWholeLineTextError(t, lerr, "surrogate")
106	
107		// 原始非法字节同值也不得误判为重复。
108		raw := []byte(`[{"name":"m` + "\xff" + `","timestamp":1,"value":7}]`)
109		_, lerr = store.IngestLine(string(raw))
110		assertWholeLineTextError(t, lerr, "UTF-8")
111	
112		// 显式 U+FFFD 数据原样保留，仍只有一条序列、一个点。
113		res := mustOK(t, store, `[]`)
114		if len(res.Series) != 1 || res.Series[0].Name != "m�" ||
115			len(res.Series[0].Points) != 1 || res.Series[0].Points[0].Value != 7 {
116			t.Fatalf("U+FFFD series changed after corrupt inputs: %+v", res.Series)
117		}
118	}
119	
120	func TestCorruptLineAtomicEvenAfterValidSamples(t *testing.T) {
121		store := NewMetricStore()
122		mustOK(t, store, `[{"name":"old","timestamp":1,"value":9}]`)
123	
124		// 数组第一个点完全合法，第二个点名称含孤立代理项：整行不得提交任何点。
125		_, lerr := store.IngestLine(`[{"name":"brandnew","timestamp":1,"value":1},{"name":"bad\uD800","timestamp":2,"value":2}]`)
126		assertWholeLineTextError(t, lerr, "surrogate")
127	
128		// 非法字节出现在后面的点同样整行回滚。
129		raw := []byte(`[{"name":"brandnew2","timestamp":1,"value":1},{"name":"bad` + "\xff" + `","timestamp":2,"value":2}]`)
130		_, lerr = store.IngestLine(string(raw))
131		assertWholeLineTextError(t, lerr, "UTF-8")
