			t.Fatalf("rejected batch must write nothing, series=%d", got)
		}
	}
}

func TestEscapedDuplicateInLaterSampleFailsWholeBatch(t *testing.T) {
	store := NewMetricStore()
	mustOK(t, store, `[{"name":"old","timestamp":1,"value":9}]`)

