				t.Fatalf("line %s must be rejected", tc.line)
			}
			assertDupFieldError(t, lerr, 1, "duplicate field")
			if got := len(mustOK(t, store, `[]`).Series); got != 0 {
				t.Fatalf("rejected batch must write nothing, series=%d", got)
