	upperEsc := string([]byte{92}) + "u006Eame"
	_, lerr := store.IngestLine(`[{"name":"m","` + upperEsc + `":"m","timestamp":1,"value":1}]`)
	assertDupFieldError(t, lerr, 1, "name")
