func jsonUnicodeSpelling(s string) string {
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		b.WriteByte(92) // JSON 转义引导符 '\'
		fmt.Fprintf(&b, "u%04x", s[i])
	}
	return b.String()
}

