		{"name":"new","timestamp":1,"value":1},
		{"name":"new","` + escName + `":"other","timestamp":2,"value":2}
	]`)
	assertDupFieldError(t, lerr, 2, "name")

	// 本批前面的合法新增点未提交；此前成功写入的 old 点数量与均值不变。
	res := mustQuery(t, store, `{"op":"query","name":"old","start":0,"end":10}`)
